@testable import Dogear
import DogearCore
import Foundation
@preconcurrency import ReadiumShared
@preconcurrency import ReadiumStreamer
import Testing

/// Seam 2: MOBI, AZW3 and FB2 converted to EPUBs in WebKit and opened in a real Readium navigator,
/// where the web reader's CFIs land on the same text (ADR 0005). Fixtures: `Fixtures/Converted`.
@MainActor
struct EPUBConverterTests {
    /// Generated by foliate-js in the web reader's way (spine step from the section index) on each
    /// fixture: the start of "The keeper wrote down 40 gulls" in Chapter Two's paragraph 40.
    @Test(.timeLimit(.minutes(3)), arguments: [
        ("LighthouseLedger", BookFile.Format.azw3, "epubcfi(/6/8!/4[chapter-two]/82/1:24)"),
        ("LighthouseLedger", .mobi, "epubcfi(/6/6!/4/84/1:24)"),
        ("LighthouseLedger", .fb2, "epubcfi(/6/8!/4/2/82/1:24)"),
    ])
    func webReaderCFILandsOnItsTextInTheConvertedEPUB(name: String, format: BookFile.Format, webReaderCFI: String) async throws {
        let reader = try await OpenReader(publication: try await converted(name, format))

        #expect(await reader.bridge.go(to: webReaderCFI))
        let visible = try #require(await reader.bridge.visibleRange())
        #expect(await reader.text(of: visible).contains("Chapter 2 paragraph 40. The keeper wrote down 40 gulls"))
        #expect(await reader.contains(visible, webReaderCFI))

        // What Dogear writes back points at the page it shows.
        let generated = try #require(await reader.bridge.currentPosition())
        #expect(await reader.bridge.isSameStart(generated, visible))
    }

    @Test func tableOfContentsComesAcrossWithEachChapter() async throws {
        let publication = try await converted("LighthouseLedger", .azw3)

        let contents = try await publication.tableOfContents().get()

        #expect(contents.compactMap(\.title) == ["Chapter One", "Chapter Two", "Chapter Three"])
        #expect(publication.metadata.title == "The Lighthouse Ledger")
    }

    @Test func drmLockedFileIsReportedAsLocked() async throws {
        let book = try Data(contentsOf: try fixture("Locked", .azw3))

        await #expect(throws: EPUBConverter.Failure.protected) { try await EPUBConverter.epub(from: book, format: .azw3) }
        await #expect(throws: EPUBConverter.Failure.unreadable) {
            try await EPUBConverter.epub(from: Data("not a book".utf8), format: .azw3)
        }
    }

    private func fixture(_ name: String, _ format: BookFile.Format) throws -> URL {
        let folder = try #require(Bundle(for: OpenReader.self).url(forResource: "Converted", withExtension: nil))
        return folder.appending(path: "\(name).\(format.rawValue)")
    }

    private func converted(_ name: String, _ format: BookFile.Format) async throws -> Publication {
        let epub = try await EPUBConverter.epub(from: try Data(contentsOf: try fixture(name, format)), format: format)
        let file = FileManager.default.temporaryDirectory.appending(path: "\(UUID().uuidString).epub")
        try epub.write(to: file)
        let httpClient = DefaultHTTPClient()
        let asset = try await AssetRetriever(httpClient: httpClient).retrieve(url: try #require(FileURL(url: file)), mediaType: .epub).get()
        return try await publicationOpener(httpClient: httpClient).open(asset: asset, allowUserInteraction: false).get()
    }
}
